INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73759, 'spa', 'de, de parte de (origen)', 'Marca la persona o lugar del que algo se origina o procede; este sentido domina con objetos en genitivo. El español traduce consistentemente de o de parte de. El genitivo señala no solo un origen físico sino también una fuente de autoridad, enseñanza o revelación, como en Mt 2:4 (aprender de los sumos sacerdotes) y Mt 21:42 (de parte del Señor).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73760, 'spa', 'junto a, cerca de', 'Adyacencia física —estar de pie, sentado o caminando junto a algo— con caso dativo. Mt 4:18 (caminando junto al mar) y 13:1 (sentado junto al mar) muestran el uso espacial literal. El español junto a subraya la cercanía; es el sentido más concreto y espacial de la preposición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73761, 'spa', 'con, en presencia de', 'Emparejado con dativo, παρά sitúa a alguien en la presencia o compañía de otro: «con» en sentido relacional y no instrumental. Mt 6:1 (recompensa ante vuestro Padre) y 19:26 (para Dios todo es posible) ilustran esta asociación. El español alterna entre con y ante, mientras que el alemán bei capta tanto la proximidad como el acompañamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73763, 'spa', 'ante, a los ojos de', 'Comparecer ante alguien en juicio o evaluación —«a los ojos de»—; este sentido conserva la proximidad espacial de estar ante el rostro de alguien pero añade la noción de escrutinio. Ro 2:11 (no hay acepción de personas ante Dios), 2:13 (justos delante de Dios) y 1 Co 3:19 (insensatez ante Dios) ejemplifican este uso. El español ante preserva la metáfora posicional en contextos morales y jurídicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73765, 'spa', 'más que, más allá de', 'En construcciones comparativas con acusativo, παρά funciona como «más que» o «más allá de», marcando el estándar de comparación. Lc 13:2 (peores que los demás galileos) y Ro 1:25 (más que al Creador) demuestran esta fuerza comparativa. El español más que y más allá de captan el sentido de exceder o sobrepasar un punto de referencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73768, 'spa', 'contra, en contra de', 'Con acusativo, παρά puede señalar oposición o desviación respecto de una norma: «contra» o «en contra de». Hch 18:13 (contra la ley) y Ro 1:26 (contra la naturaleza) muestran esta fuerza de oposición. El sentido espacial de «junto a» se desplaza a «al lado pero desviándose de», subrayando el apartarse de un camino o norma esperados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73774, 'spa', 'aparte de, excepto', 'Exclusión o excepción: «aparte de», «excepto», «además de»; aparece con acusativo. 1 Co 3:11 (ningún fundamento aparte de Jesucristo), 2 Co 11:24 (cuarenta azotes menos uno) y Gá 1:8-9 (evangelio diferente del que predicamos) muestran este sentido restrictivo. El español aparte de marca el límite entre lo incluido y lo excluido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73779, 'spa', 'por, a causa de', 'Dos apariciones en 1 Co 12:15-16 resisten una clasificación fácil; posiblemente causal o relativa a evaluación («por esta razón»). El español por sugiere un vínculo causal o explicativo difuso. El sentido permanece infradeterminado por el contexto sintáctico y semántico inmediato, a la espera de mayor evidencia de corpus o refinamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73780, 'spa', 'entre, en medio de', 'Estar «entre» un grupo o comunidad; παρά con dativo o acusativo según haya o no movimiento. Mt 28:15 (divulgado entre los judíos) y Col 4:16 (leído entre los laodicenses) ilustran la presencia comunitaria. El español entre capta el sentido de estar situado dentro de un colectivo, extendiendo la proximidad de persona a persona hacia relaciones de uno a muchos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73792, 'spa', 'Transgredir límites', 'Las traducciones multilingües enfatizan la violación y la desviación. El léxico traza el desarrollo semántico de ''ir al lado de'' a ''sobrepasar, transgredir''. Mateo 15:2-3 lo usa dos veces para contrastar la violación de la tradición con la del mandamiento divino, mientras que Hechos 1:25 describe la deserción de Judas de su ministerio apostólico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73793, 'spa', 'Arribar a puerto', 'Acts 20:15 relata: ''Navegamos de allí... y al día siguiente llegamos a Samos''. El verbo describe la llegada del barco a un puerto durante el viaje de regreso de Pablo a Jerusalén. El contexto náutico indica que se refiere a tocar o alcanzar un fondeadero, parte de la navegación costera por el Egeo. Cada arribo marca avance hacia el destino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73794, 'spa', 'Transgresión de la ley', 'Transgresión, violación de la ley: el acto de traspasar conscientemente un límite o mandamiento divino. El uso paulino es teológicamente preciso: la transgresión requiere una ley promulgada que transgredir (Ro 4:15), y la ley misma fue dada ''a causa de las transgresiones'' (Gá 3:19). En Ro 5:14 quienes pecaron antes de Moisés no pecaron ''a la semejanza de la transgresión de Adán'', resaltando la naturaleza formal y consciente del acto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73797, 'spa', 'Transgresor de la ley', 'Transgresor o infractor de la ley: quien cruza la linea que la ley divina o moral ha trazado. En Romanos 2:25-27, Pablo usa este termino para cuestionar la confianza judia en la circuncision: la circuncision fisica se convierte en incircuncision si uno es παραβάτης de la ley, mientras que el incircunciso que la cumple juzgara al transgresor circunciso. Galatas 2:18 vuelve el cargo reflexivamente: reconstruir lo demolido hace de uno mismo un transgresor. Santiago 2:9 y 2:11 lo democratizan: fallar en un solo punto convierte en culpable de toda la ley.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73799, 'spa', 'Parábola, comparación ilustrativa', 'Narración figurada, comparación o dicho proverbial puesto junto a una verdad para iluminarla, funcionando como vehículo principal de la enseñanza de Jesús sobre el reino. Abarca parábolas narrativas extensas (el Sembrador, Mt 13:3-9; los Labradores malvados, Mt 21:33-44), símiles compactos (la Levadura, Mt 13:33; la Perla, Mt 13:45-46) y dichos enigmáticos que se acercan al proverbio (Lc 4:23, ''Médico, cúrate a ti mismo'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73802, 'spa', 'Arriesgar la vida', 'Philippians 2:30 honra a Epafrodito porque ''estuvo próximo a la muerte por la obra de Cristo, habiendo arriesgado su vida'' para servir a Pablo. El participio subraya la naturaleza deliberada del riesgo: no fue peligro accidental, sino elección consciente de exponerse. Pablo presenta este servicio como ejemplo de humildad cristiana: considerar a los demás más importantes que uno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73803, 'spa', 'Mandamiento autoritativo', 'Un mandamiento o encargo con autoridad, instrucciones dadas con el peso del rango o del cargo, ya sea de un concilio religioso, un superior militar o un apóstol. El término conserva el matiz de su origen castrense: órdenes transmitidas por una cadena de mando. En Hechos 5:28, la orden del sumo sacerdote tiene fuerza legal. En 1 Tesalonicenses 4:2, Pablo recuerda a los creyentes las παραγγελίαι que les dio «por medio del Señor Jesús».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73804, 'spa', 'Mandar u ordenar con autoridad', 'Mandar u ordenar con autoridad. Mandato o directiva autoritativa emitida desde una posición de liderazgo —militar, apostólico o dominical. Jesús ordena a la multitud recostarse antes de la multiplicación (Mt 15:35; Mr 8:6), y los apóstoles emiten directivas vinculantes a la iglesia primitiva (Hch 16:18; 1 Ts 4:11). El término presupone una cadena de mando establecida y la expectativa de obediencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73805, 'spa', 'Encargar o instruir con urgencia', 'Encargar o instruir con urgencia. Encargo solemne o instrucción pastoral, donde el tono es de exhortación personal más que de mera orden. Pablo «encarga» a Timoteo permanecer en Éfeso y combatir la falsa enseñanza (1 Ti 1:3), y dice a los corintios «os instruyo» respecto a la Cena del Señor (1 Co 11:17). Combina autoridad con urgencia pastoral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73823, 'spa', 'Llegar a un lugar', 'Llegar a un lugar. Arribo físico a un lugar o destino específico, con énfasis en la consumación del viaje. Es el sentido dominante (31 apariciones): los magos llegando a Jerusalén (Mt 2:1), los mensajeros alcanzando a Jesús (Lc 7:4, 20), la familia de María viniendo a buscarlo (Lc 8:19) y viajeros que arriban tras un trayecto (Lc 11:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73828, 'spa', 'Aparecer, presentarse en escena', 'Aparecer, presentarse en escena. Aparición dramática o pública, marcando el debut de una figura significativa o el inicio de un momento decisivo. Juan el Bautista aparece predicando en el desierto (Mt 3:1), Jesús llega al Jordán para su bautismo (Mt 3:13), Judas se presenta con la turba armada en Getsemaní (Mr 14:43) y Cristo aparece como sumo sacerdote de los bienes venideros (He 9:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73832, 'spa', 'Estar presente, acudir junto a alguien', 'Estar presente, acudir junto a alguien. Estar presente en un lugar o acudir al lado de alguien, con énfasis en la asistencia o compañía más que en el acto de viajar. Los hermanos estaban presentes cuando Pablo llegó a Jerusalén (Hch 21:18) y nadie estuvo al lado de Pablo en su primera defensa (2 Ti 4:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73841, 'spa', 'Pasar (movimiento fisico)', 'Pasar (movimiento fisico). Pasar fisicamente, caminar o transitar junto a un lugar. Usado de Jesus desplazandose por pueblos y caminos: divisando a Mateo en el puesto de cobro de impuestos (Mateo 9:9), caminando junto al Mar de Galilea (Marcos 1:16, Marcos 2:14), o pasando mientras ciegos claman a el (Mateo 9:27, Mateo 20:30). El verbo transmite locomocion humana ordinaria que, en las narrativas evangelicas, se convierte en ocasion para encuentros extraordinarios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73842, 'spa', 'Pasar (sentido metaforico/temporal)', 'Pasar (sentido metaforico/temporal). Pasar, dejar de existir: extension metaforica que describe la transitoriedad del orden mundial presente. Pablo declara que ''la apariencia de este mundo se esta pasando'' (1 Corintios 7:31), y Juan escribe que ''las tinieblas se estan pasando'' mientras la luz verdadera resplandece (1 Juan 2:8) y ''el mundo y sus deseos se estan pasando'' (1 Juan 2:17). El desplazamiento del movimiento fisico a la impermanencia cosmica es un giro dramatico de significado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73846, 'spa', 'Exponer a vergüenza', 'Hebrews 6:6 advierte que quienes caen ''están crucificando de nuevo al Hijo de Dios y exponiéndolo al vituperio'', usando este verbo para la humillación pública. Renunciar a Cristo tras ser iluminado equivale a tratar su crucifixión como merecida, repudiándolo públicamente. La frase participial subraya la gravedad de la apostasía: no se aleja en silencio, sino que avergüenza a Cristo abiertamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73847, 'spa', 'Paraiso divino', 'Todas las lenguas preservan o transliteran el termino: espanol ''Paraiso'', frances ''paradis'', aleman ''Paradies''. El lexico traza su origen desde los parques persas hasta el jardin del Eden (LXX) y la morada de los bienaventurados (NT). Lucas 23:43 promete al ladron la presencia inmediata con Cristo en el Paraiso. 2 Corintios 12:4 describe la ascension visionaria de Pablo. Apocalipsis 2:7 situa el arbol de la vida en el paraiso de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73848, 'spa', 'Recibir y acoger', 'Recibir, aceptar o acoger algo o a alguien que se ofrece o presenta, con disposición abierta y voluntaria. Se emplea para recibir el evangelio (Marcos 4:20), dar la bienvenida a apóstoles (Hechos 15:4), aceptar prácticas (Hechos 16:21) y admitir acusaciones (1 Tim 5:19). El énfasis siempre recae en la receptividad intencional y activa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73854, 'spa', 'Disputas constantes', '1 Timothy 6:5 describe a los maestros corruptos como marcados por ''fricciones constantes'', disputas interminables que agotan y dividen. El sustantivo capta la naturaleza estéril y repetitiva de sus controversias: no indagación honesta, sino regateo interminable. Pablo advierte a Timoteo contra aquellos cuyas mentes están ''depravadas y privadas de la verdad'', cuya enseñanza produce fricción, no fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73855, 'spa', 'entregar, poner en custodia', 'Entregar o poner a una persona en custodia (78×): el sentido dominante, que cubre la transferencia de alguien al poder, control o jurisdicción de otro —tribunales, gobernantes, cárceles u opositores— sin implicar traición personal por parte del agente. Jesús anuncia a los discípulos que serán entregados a tribunales (Mt 10:17). El español entregó cubre esta transferencia neutral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73856, 'spa', 'traicionar, entregar con perfidia', 'Traicionar, entregar de modo desleal (20×): una intensificación especializada del sentido 1 en la que la transferencia implica deslealtad personal, quebrantamiento de confianza o perfidia desde dentro. Prototípicamente Judas: identificado como «el que lo iba a entregar» (Mt 10:4; 26:25), negocia el precio y consuma la traición con un beso. El contexto narrativo de confianza rota distingue este sentido de la mera custodia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73866, 'spa', 'transmitir, pasar tradición', 'Transmitir tradición o enseñanza (12×): el sentido catequético, donde lo que se «entrega» no es una persona sino instrucción autoritativa, decretos o práctica heredada. La fórmula paulina es definitiva: «Os entregué lo que asimismo recibí» (1 Co 11:23; 15:3), estableciendo un vocabulario técnico de tradición. El español transmitir marca el registro de transmisión frente a la entrega física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73869, 'spa', 'encomendar, confiar al cuidado', 'Encomendar o confiar al cuidado de alguien (5×): entregar algo valioso —responsabilidad, autoridad o recursos— para su administración. En la parábola de los talentos, el amo «entregó» cinco talentos a un siervo (Mt 25:20, 22). Satanás afirma que la autoridad le ha sido «entregada» (Lc 4:6). El español encomendado distingue claramente el matiz fiduciario del coercitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73880, 'spa', 'abandonar, entregar a un destino', 'Entregar, abandonar o ceder a una condición (4×): rendir a alguien (o a uno mismo) a un poder, destino o experiencia, ya sea juicio divino, autoentrega sacrificial o exposición voluntaria. Dios «los entregó» a sus deseos pecaminosos (Ro 1:24, 26, 28); Pablo habla de quienes «arriesgaron sus vidas» (Hch 15:26). El español entregar con matiz de abandono capta esta rendición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73892, 'spa', 'permitir, dar lugar', 'Permitir que un proceso siga su curso (1×): en Mr 4:29, cuando el grano está maduro, el labrador «mete la hoz» porque la cosecha «lo permite» —el fruto se ha entregado a la madurez. Una vívida metáfora agrícola donde el cultivo maduro se imagina rindiéndose a la siega, un uso singular e irrepetible de παραδίδωμι en el Nuevo Testamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73909, 'spa', 'Cosas asombrosas e inesperadas', 'En Lucas 5:26, la multitud responde a la sanidad del paralítico: «Hoy hemos visto cosas increíbles». El adjetivo capta su estupor: no son meros actos impresionantes, sino sucesos que desafían toda expectativa. El paralítico caminó, los pecados fueron perdonados, la autoridad divina se manifestó. Lo presenciado trastornó sus categorías, produciendo temor y glorificación a Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73910, 'spa', 'Enseñanza, práctica o costumbre transmitida con autoridad de una generación o au', 'Enseñanza, práctica o costumbre transmitida con autoridad de una generación o autoridad a la siguiente. Se usa tanto negativamente, refiriéndose a tradiciones humanas que anulan la palabra de Dios (Mt 15:2-3, 6; Mc 7:3, 5, 8-9, 13; Col 2:8; Gá 1:14), como positivamente, refiriéndose a tradiciones apostólicas que deben mantenerse (1 Co 11:2; 2 Ts 2:15; 3:6). El concepto de παράδοσις presupone una cadena de transmisión — alguien entrega y otro recibe — lo que lo convierte en un término teológicamente decisivo para la relación entre tradición y Escritura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73912, 'spa', 'Provocar a celos', 'Provocar deliberadamente a celos, suscitar rivalidad celosa o envidia, especialmente en un contexto pactual o relacional. El argumento de Pablo en Romanos 10-11 gira sobre este verbo: Dios provoca a Israel a celos mediante la inclusión de los gentiles (Rom 10:19, citando Dt 32:21), y Pablo espera que su ministerio gentil provoque a sus hermanos a celos salvíficos (Rom 11:11, 14). En 1 Corintios 10:22 el objeto cambia al Señor mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73913, 'spa', 'Costero, junto al mar', 'En Mateo 4:13, Jesús deja Nazaret para establecerse en Capernaúm «junto al mar», en la costa galileana. Este marcador geográfico cumple doble función: ubica históricamente el ministerio y cumple la profecía de Isaías sobre la luz que amanece en «Galilea de los gentiles». El entorno costero adquiere significado teológico como lugar donde el Mesías inicia su ministerio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73914, 'spa', 'Descuidar por inadvertencia', 'En Hechos 6:1, los judíos helenistas se quejan de que «sus viudas eran desatendidas en la distribución diaria». El verbo pasivo indica que sufrían negligencia, fuera intencional o no. Esta desatención amenazó la unidad eclesial y motivó el nombramiento de diáconos para garantizar un cuidado equitativo. El verbo subraya que las buenas intenciones no aseguran resultados justos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73915, 'spa', 'Deposito sagrado', 'Las traducciones multilingues lo rinden uniformemente como ''deposito'': espanol ''deposito'', frances conserva el griego παραθήκην, aleman ''anvertrautes Gut'' (bien confiado). El lexico lo define como ''cualquier cosa confiada a alguien'', con raices en la banca y la propiedad. 1 Timoteo 6:20 y 2 Timoteo 1:14 exhortan a Timoteo a guardar el deposito (la sana doctrina), mientras que 2 Timoteo 1:12 expresa la confianza de Pablo en Cristo como guardian.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73917, 'spa', 'Rechazar, rehusar o declinar con firmeza — el uso dominante en el Nuevo Testamen', 'Rechazar, rehusar o declinar con firmeza — el uso dominante en el Nuevo Testamento, donde algo se desestima o se aparta. Pablo ordena a Timoteo «rechazar» los mitos profanos (1 Ti 4:7), «rehusar» a las viudas jóvenes de la lista (1 Ti 5:11) y evitar las controversias necias (2 Ti 2:23). Hebreos 12:25 advierte contra rechazar al que habla desde el cielo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73918, 'spa', 'Excusarse o disculparse de una obligación o invitación, ofreciendo razones para ', 'Excusarse o disculparse de una obligación o invitación, ofreciendo razones para declinar. En la parábola del gran banquete (Lc 14:18-19), cada invitado «comenzó a excusarse»: uno compró un campo, otro bueyes, otro se casó. El matiz es de declinación cortés y social, distinto del rechazo tajante del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73919, 'spa', 'Hacer una solicitud o súplica encarecida — el sentido clásico de rogar o pedir', 'Hacer una solicitud o súplica encarecida — el sentido clásico de rogar o pedir. En Marcos 15:6, la multitud «pedía» que Pilato liberara a un preso, y en Hebreos 12:19 los israelitas en el Sinaí «suplicaron» que no se les siguiera hablando. Este registro suplicatorio revela la amplitud semántica del verbo, que abarca desde el ruego hasta el rechazo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73926, 'spa', 'Sentarse como discípulo', 'En Lucas 10:39, María se «sentó junto a los pies del Señor» para escuchar su enseñanza. El participio capta su decisión deliberada de asumir la posición del discípulo. En contraste con Marta, su postura demuestra concentración singular: ha elegido la cercanía a Jesús y la atención a su palabra. Su posición física refleja su entrega espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73927, 'spa', 'rogar, suplicar, implorar', 'Rogar, suplicar o implorar: el grupo más numeroso con 57 apariciones. Es el παρακαλέω de la petición desesperada: el centurión rogando a Jesús que sane a su siervo (Mt 8:5), los demonios gadarenos suplicando entrar en los cerdos (Mt 8:31), la hemorroísa acercándose tras la presión de la multitud (Mr 5:23). El sujeto se halla típicamente en posición de necesidad, apelando a la autoridad o compasión del otro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73930, 'spa', 'exhortar, amonestar, instar', 'Exhortar, amonestar o instar a la conducta recta: 28 apariciones, concentradas en Hechos y las epístolas paulinas. Es el παρακαλέω pastoral: Bernabé exhortando a los creyentes de Antioquía a permanecer fieles (Hch 11:23), Pablo y Silas fortaleciendo las iglesias (Hch 14:22; 15:32), y la fórmula epistolar recurrente «os exhorto, hermanos» (Ro 12:1; 1 Ts 4:1). La dirección pasa de pedir hacia arriba a instar hacia adelante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73937, 'spa', 'consolar, dar consuelo', 'Consolar o dar alivio al afligido: 11 apariciones, con 2 Corintios como epicentro. El «Dios de toda consolación que nos consuela en toda tribulación» de Pablo (2 Co 1:3-4) emplea este verbo cuatro veces en dos versículos, estableciendo el consuelo como atributo divino canalizado a través de la comunidad humana. Los tesalonicenses deben «consolarse unos a otros» respecto de los difuntos (1 Ts 4:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73947, 'spa', 'ser consolado, recibir consuelo', 'Ser consolado o recibir consolación (voz pasiva/media): 11 apariciones donde el sujeto experimenta el consuelo en vez de dispensarlo. La bienaventuranza «ellos serán consolados» (Mt 5:4) es el caso más célebre. Raquel «no quiso ser consolada» por sus hijos (Mt 2:18). En 2 Co 7:6-7, Pablo mismo «fue consolado» por la llegada de Tito. El español ser consolado y el alemán getröstet werden reflejan esta receptividad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73961, 'spa', 'invitar, convocar', 'Invitar, convocar o solicitar la presencia de alguien: solo 2 apariciones claras, ambas en Hechos. En Hch 28:14 los compañeros de Pablo «fueron invitados» a quedarse con los creyentes; en Hch 28:20 Pablo explica que «convocó» a los líderes judíos de Roma. Este sentido recupera el significado del griego clásico más cercano a la etimología («llamar al lado»), en gran medida eclipsado por la súplica y el consuelo en el Nuevo Testamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73981, 'spa', 'Ocultar del entendimiento', 'La forma pasiva perfecta aparece en Lucas 9:45, donde la declaración de Jesús sobre su traición estaba «encubierta» para los discípulos. La evidencia multilingüe (inglés «hidden», español «encubierta», francés «voilé») apunta consistentemente al ocultamiento. La asignación al dominio de la vida mental refleja cómo este encubrimiento produce opacidad cognitiva: los discípulos no podían penetrar el velo que cubría el significado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73983, 'spa', 'Consuelo o consolación ofrecida a quienes sufren, se lamentan o enfrentan tribul', 'Consuelo o consolación ofrecida a quienes sufren, se lamentan o enfrentan tribulación: la dimensión pastoral y terapéutica de la palabra. Dios es el «Dios de toda consolación» que nos consuela para que podamos consolar a otros (2 Cor 1:3-7). Simeón esperaba la παράκλησιν de Israel (Lc 2:25), y los ricos ya han recibido la suya (Lc 6:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73984, 'spa', 'Ánimo o exhortación que impulsa a los creyentes hacia la fidelidad, la conducta ', 'Ánimo o exhortación que impulsa a los creyentes hacia la fidelidad, la conducta recta o el crecimiento espiritual. Bernabé es υἱὸς παρακλήσεως, «hijo de consolación» (Hch 4:36), y la iglesia crece en la παράκλησις del Espíritu Santo (Hch 9:31). Pablo la sitúa junto a la enseñanza y la lectura de las Escrituras (1 Tim 4:13) y la incluye como don espiritual (Rom 12:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73987, 'spa', 'Súplica, ruego o petición urgente dirigida a otros', 'Súplica, ruego o petición urgente dirigida a otros. En 2 Cor 8:4, los macedonios piden con mucha παράκλησις el privilegio de participar en la ofrenda, y el propio Tito actúa con entusiasmo sin necesitar παράκλησις (2 Cor 8:17). El énfasis recae en la intensidad del que pide, más que en la edificación del que recibe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73992, 'spa', 'Abogado y consolador', 'Un abogado, ayudador o consolador: alguien convocado para estar junto a otro en su apoyo, ya sea como defensor legal o como compañero que fortalece. El término tiene raíces forenses (un asistente legal en los tribunales), lo cual aflora en 1 Juan 2:1 donde Cristo resucitado sirve como nuestro παράκλητος ante el Padre. En el Discurso de Despedida de Juan, Jesús llama al Espíritu Santo «otro Paráclito» (ἄλλον παράκλητον), señalando la continuidad de su propia misión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73993, 'spa', 'Desobediencia deliberada', 'La evidencia interlingue indica uniformemente desobediencia: espanol ''desobediencia'', frances ''desobeissance'', aleman ''Ungehorsam''. El lexico traza el desarrollo semantico desde ''oir imperfectamente'' hasta ''negativa a escuchar, desobediencia, contumacia''. Los tres usos neotestamentarios se refieren a desobediencia deliberada: la de Adan contrastada con la obediencia de Cristo (Romanos 5:19), la advertencia a Corinto (2 Corintios 10:6) y la de Hebreos 2:2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73994, 'spa', 'Seguimiento atento', 'Las traducciones multilingues destacan el seguimiento cuidadoso: espanol ''habiendo seguido/has seguido'', frances ''suivre'', aleman ''nachfolgen''. El lexico senala significados desde ''seguir o atender de cerca'' hasta ''investigar con exactitud''. Lucas 1:3 lo usa para describir su investigacion rigurosa ''desde el principio''; 1 Timoteo 4:6 elogia a Timoteo por nutrirse en la sana doctrina; 2 Timoteo 3:10 destaca el seguimiento fiel de la ensenanza y vida de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73995, 'spa', 'Desoir o ignorar', 'La evidencia interlingue muestra tanto el sentido de oir por casualidad como el de negarse a escuchar: espanol ''ignorando/rehusare oir'', frances ''negliger'', aleman ''nicht horen''. El lexico enumera multiples acepciones: ''oir al lado/accidentalmente'', ''oir imperfectamente'', ''no prestar atencion'', ''desobedecer'', ''fingir no oir''. Marcos 5:36 presenta a Jesus ''oyendo'' (o ''ignorando'') la noticia sobre la hija de Jairo, mientras que Mateo 18:17 se refiere a la negativa deliberada a escuchar la correccion eclesial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73996, 'spa', 'Inclinarse para escudriñar', 'Inclinarse para mirar con atención intensa, agacharse y asomarse a algo con enfoque deliberado. El verbo combina una postura física (inclinarse, agacharse) con una mirada intencionada. En los relatos del sepulcro, Pedro (Lc 24:12), el discípulo amado (Jn 20:5) y María Magdalena (Jn 20:11) realizan el gesto de παρακύπτω hacia la tumba vacía. Santiago 1:25 traslada la imagen al plano espiritual: quien se inclina sobre la ley perfecta y persevera, actúa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73997, 'spa', 'Tomar consigo, llevar', 'Tomar consigo, llevar o escoltar. Acompañamiento físico: trasladar a una persona o cosa de un lugar a otro. Predomina en los relatos de la infancia (Mt 1:20, 24; 2:13-14, 20-21, donde José toma a su familia), en Jesús llevando aparte a los discípulos (Mt 17:1; 20:17), y en los dichos escatológicos sobre ser ''tomado'' o ''dejado'' (Mt 24:40-41; Lc 17:34-35).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74000, 'spa', 'Recibir lo transmitido', 'Recibir o aceptar lo que es transmitido: una tradición, enseñanza, mensaje o autoridad pasada de una parte a otra. El prefijo παρά- subraya la dimensión de ''procedente de otro'' en la recepción. El uso técnico paulino es especialmente relevante: ''lo que recibí, os lo transmití'' (1 Co 11:23; 15:1-3), estableciendo la cadena de tradición apostólica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74019, 'spa', 'Región costera', 'Lucas 6:17 emplea este adjetivo para describir la ''región costera'' (παραλίου) de Tiro y Sidón. Las traducciones en diversos idiomas (inglés ''coastal'', español ''costa'', francés ''côte'') reflejan uniformemente la geografía marítima. Gentes de estas ciudades fenicias costeras viajaron tierra adentro hasta Galilea para encontrarse con Jesús, evidenciando el poder de atracción de su ministerio más allá de las fronteras regionales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74020, 'spa', 'Variación o mudanza', 'Santiago 1:17 declara que en el Padre de las luces no hay ''variación'' (παραλλαγή), contrastando la inmutabilidad divina con los cambios observables del sol, la luna y las estrellas. Las traducciones preservan este sentido de cambio o alteración. La fuerza retórica depende del trasfondo astronómico: mientras los cuerpos celestes cambian y proyectan sombras variables, Dios permanece constante en su bondad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74022, 'spa', 'Paralítico, persona paralizada — persona afligida por parálisis, incapaz de move', 'Paralítico, persona paralizada — persona afligida por parálisis, incapaz de mover uno o más miembros; se emplea como adjetivo sustantivado en los relatos sinópticos de sanación. Aparece en el milagro de Capernaúm donde bajan al paralítico por el techo (Mt 9:2,6; Mc 2:3-5,9-10), en el resumen galileo de los enfermos traídos a Jesús (Mt 4:24) y en el episodio del siervo del centurión (Mt 8:6). Las formas singular y plural representan flexión de número de un único significado léxico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74025, 'spa', 'Paralizar o debilitar', 'Estar paralizado, debilitado o incapacitado, usado en el NT en voz pasiva para describir cuerpos o miembros que han perdido su función. El sentido raíz es «aflojar» (de λύω), con el prefijo παρα- sugiriendo un aflojamiento lateral, es decir, quedar laxo. En Lucas 5:18, 24, un hombre παραλελυμένος es llevado en camilla y sanado por Jesús. Hechos 8:7 y 9:33 extienden este uso a los ministerios de sanidad de Felipe y Pedro. Hebreos 12:12 lo traslada al ámbito espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74026, 'spa', 'Permanecer con fidelidad', 'Permanecer junto a alguien, continuar al lado, perseverar en una relación, un lugar o un compromiso. Las traducciones convergen en presencia leal y sostenida: español permanecer, alemán bleiben, francés demeurer. Pablo lo usa para seguir vivo en beneficio de las iglesias (Fil 1:25), mientras que Hebreos 7:23 contrasta a sacerdotes mortales con el sacerdocio permanente de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74027, 'spa', 'Consolar y animar', 'Consolar, confortar y animar, acercándose a alguien en duelo o desánimo para ofrecerle palabras de fortaleza. La evidencia multilingüe (español consolad, alemán trösten, francés consoler) se agrupa en torno al consuelo profundo. Juan 11:19 y 11:31 lo muestran en el duelo por Lázaro, y 1 Tesalonicenses 2:12 y 5:14 revelan su faceta pastoral de exhortación tierna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74028, 'spa', 'Consolación espiritual', 'En 1 Corintios 14:3, la profecía proporciona ''consolación'' (παραμυθίαν) junto con la edificación y la exhortación. Las traducciones multilingües (español ''consolación'', francés ''consolation'', alemán ''Trost'') enfatizan consistentemente el consuelo a quienes sufren o luchan. La tríada de Pablo muestra que la palabra inspirada por el Espíritu no solo instruye, sino que también reconforta y alienta, atendiendo necesidades emocionales y espirituales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74029, 'spa', 'Consuelo en Cristo', 'Filipenses 2:1 pregunta retóricamente si hay algún ''consuelo'' (παραμύθιον) en Cristo. Las traducciones (inglés ''comfort'', español ''consuelo'', alemán ''Ermutigung'') resaltan la dimensión consoladora. Pablo encadena cuatro cláusulas condicionales para fundamentar su llamado a la unidad: estímulo en Cristo, consuelo del amor, comunión del Espíritu, y afecto y compasión. El consuelo no es abstracto sino relacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74030, 'spa', 'Transgredir la ley', 'Hechos 23:3 presenta a Pablo denunciando al sumo sacerdote por ''actuar contra la ley'' (παρανομῶν) al ordenar que lo golpearan. Las traducciones (inglés ''acting contrary to law'', español ''transgrediendo la ley'', francés ''agir illégalement'') captan la transgresión legal. La ironía es demoledora: quien debería defender la Torá la viola, ordenando violencia contra un hombre sin sentencia. La reprensión de Pablo expone esa contradicción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74031, 'spa', 'Transgresión de la ley', 'En 2 Pedro 2:16 se describe la reprensión de la burra ante la «ilegalidad» (παρανομίας) del profeta, es decir, la transgresión de Balaam al buscar recompensa por maldecir a Israel. Las traducciones resaltan la violación del mandato divino. El absurdo subraya una inversión moral: un animal mudo se convierte en vehículo de reprensión racional, conteniendo la locura profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74032, 'spa', 'Rebelión provocadora', 'Hebreos 3:16 pregunta quiénes «se rebelaron» (παρεπίκραναν) tras el éxodo. Las traducciones apuntan a provocación y rebeldía. La respuesta retórica es devastadora: no solo algunos, sino casi toda la generación del éxodo que escuchó a Moisés murió en el desierto por incredulidad. Su rebelión convirtió la liberación divina en motivo de juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74034, 'spa', 'Apostasía decisiva', 'Hebreos 6:6 describe a quienes «habiendo caído» (παραπεσόντας) no pueden ser renovados al arrepentimiento. Las traducciones enfatizan la apostasía definitiva. La severidad del pasaje ha inquietado a los intérpretes durante siglos, pero la evidencia lingüística es clara: esta caída es completa y catastrófica, un repudio total de la gracia previamente experimentada que cierra el camino de retorno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74035, 'spa', 'Pasar de largo navegando', 'Hechos 20:16 registra la decisión de Pablo de «pasar de largo» (παραπλεῦσαι) Éfeso rumbo a Jerusalén. Las traducciones conservan el sentido náutico de bordeamiento. La elección refleja priorización misionera: aunque Éfeso albergaba relaciones ministeriales profundas, la urgencia de llegar a Jerusalén para Pentecostés exigió seguir navegando. Las limitaciones de tiempo dictaron sacrificar la visita pastoral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74036, 'spa', 'Proximidad extrema', 'Filipenses 2:27 describe a Epafrodito enfermo «cercano» (παραπλήσιον) a la muerte. Las traducciones enfatizan la proximidad al límite fatal. El relato de Pablo valida tanto el sacrificio de Epafrodito como la misericordia de Dios: la enfermedad no fue un inconveniente menor sino un roce con la muerte al servicio del evangelio. El lenguaje de cercanía honra la entrega genuina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74037, 'spa', 'De igual manera', 'Hebreos 2:14 declara que Jesús ''igualmente'' (παραπλησίως) participó de carne y sangre. Las traducciones (''likewise'', ''de-modo-similar'', ''ebenso'') resaltan la manera comparable. El peso teológico es inmenso: el Hijo de Dios entró en la existencia humana no de forma protegida ni modificada, sino plena y genuinamente, en el mismo modo que aquellos a quienes vino a salvar. La verdadera encarnación exige participación completa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74038, 'spa', 'Pasar al lado', 'Pasar junto a algo o caminar al lado de un lugar sin detenerse como propósito principal. El prefijo παρα- aporta el matiz de «junto a». Las escenas de la crucifixión (Mt 27:39; Mc 15:29) muestran transeúntes que lanzan insultos, captando la cruel indiferencia de quienes pasan de largo. Marcos 2:23 presenta a los discípulos junto a los campos de grano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74039, 'spa', 'Una transgresión o falta moral, literalmente un «caer al lado» del camino recto', 'Una transgresión o falta moral, literalmente un «caer al lado» del camino recto. Aunque la etimología sugiere un desliz involuntario, el uso neotestamentario abarca desde ofensas cotidianas que los creyentes deben perdonarse mutuamente (Mt 6:14-15; Mc 11:25) hasta la caída catastrófica de Adán que trajo la muerte a toda la humanidad (Rom 5:15-18). Pablo le otorga un peso serio, usándola para la transgresión primordial de Adán en Romanos 5:15-20 y para las ofensas que demandaron la muerte expiatoria de Cristo en Efesios 2:1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74045, 'spa', 'Apartarse gradualmente', 'Hebreos 2:1 advierte que no ''nos deslicemos'' (παραρρυῶμεν) del mensaje recibido. Las traducciones (''drift-away'', ''nos-deslicemos'', ''abtreiben'') capturan el dejarse llevar pasivamente lejos del ancla. El peligro no es la rebelión activa sino la desatención pasiva: la corriente sutil que arrastra al creyente descuidado lejos de la verdad. El llamado a prestar mayor atención reconoce que la vigilancia constante es esencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74046, 'spa', 'Con insignia distintiva', 'Hechos 28:11 menciona un barco alejandrino ''con la insignia'' (παρασήμῳ) de los Dióscuros (Cástor y Pólux). Las traducciones (''with-figurehead'', ''con-insignia'', ''marque'') apuntan al emblema del navío. Los marineros antiguos confiaban en estos gemelos divinos para proteger sus travesías. El detalle de Lucas revela a Pablo navegando en un barco con insignias paganas, un toque narrativo que muestra cómo el evangelio avanza dentro del mundo gentil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74047, 'spa', 'Preparar con anticipación', 'Preparar, alistar o equipar con antelación para un evento o necesidad venideros. Las tradiciones traductoras coinciden — español preparar, alemán vorbereiten, francés préparer — en disposición deliberada y previsora. Hechos 10:10 lo aplica a preparar una comida, 1 Corintios 14:8 a la disposición para la batalla, y 2 Corintios 9:2-3 a la generosa disposición financiera de los corintios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74048, 'spa', 'Día de Preparación', 'El día de preparación previo al sábado o a una festividad judía mayor, específicamente el viernes, cuando todo trabajo y la preparación de alimentos debían completarse antes de la puesta del sol. Cada aparición neotestamentaria (Mat 27:62; Mar 15:42; Luc 23:54; Juan 19:14, 31) se sitúa en el relato de la Pasión, fijando la crucifixión en viernes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74051, 'spa', 'Prolongar el discurso', 'Hechos 20:7 narra cómo Pablo ''extendió'' (παρέτεινεν) su mensaje hasta la medianoche antes de partir. Las traducciones (''extended'', ''extendió'', ''étendre'') enfatizan la prolongación temporal. El extenso discurso de Pablo, que continuó hasta que Eutico cayó de la ventana a medianoche, muestra la urgencia apostólica: cuando el tiempo es limitado y el momento de enseñanza es fecundo, ni siquiera la medianoche pone fin a la predicación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74052, 'spa', 'Observar de cerca', 'Observar de cerca, vigilar con atención sostenida o mantener bajo vigilancia, frecuentemente con intención hostil o sospechosa. La evidencia multilingüe es coherente: el español «observar», el francés «observer» y el alemán «beobachten» denotan observación cuidadosa y metódica. En los Evangelios sinópticos, el término aparece en contextos de confrontación: los fariseos escrutando a Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74058, 'spa', 'Observación escrutadora', 'Lucas 17:20 declara que el reino de Dios no viene ''con observación'' (παρατηρήσεως), no como un fenómeno visible que los fariseos puedan vigilar y medir. Las traducciones (''observation'', ''observación'', ''observation'') conservan el tema de la vigilancia. Jesús rechaza la idea de que el reino llegue como un evento empíricamente observable con indicadores claros. Viene de otro modo: entre y dentro de las personas, escapando a toda cuantificación humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74059, 'spa', 'Poner comida o provisiones delante de alguien, servir a la mesa', 'Poner comida o provisiones delante de alguien, servir a la mesa. Este sentido primario (11 apariciones) domina los relatos de alimentación: Jesús parte los panes y los da a los discípulos para que los pongan delante de la multitud (Mr 6:41; 8:6-7), la casa de Marta sirve una comida (Lc 10:8) y Pablo aconseja ''comed de todo lo que os pongan delante'' (1 Co 10:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74062, 'spa', 'Encomendar, confiar o entregar a alguien o algo al cuidado y protección de otro', 'Encomendar, confiar o entregar a alguien o algo al cuidado y protección de otro. Con 7 apariciones, este sentido en voz media lleva un peso relacional profundo: Jesús clama ''Padre, en tus manos encomiendo mi espíritu'' (Lc 23:46), Pablo y Bernabé encomiendan a los nuevos creyentes al Señor (Hch 14:23) y Pablo encomienda a los ancianos de Éfeso a Dios y a la palabra de su gracia (Hch 20:32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74071, 'spa', 'Exponer, presentar o explicar un argumento o enseñanza ante un auditorio', 'Exponer, presentar o explicar un argumento o enseñanza ante un auditorio: el equivalente intelectual de servir una comida. Solo 1 aparición clara: en Hch 17:3 Pablo está en la sinagoga de Tesalónica ''exponiendo y demostrando que era necesario que el Cristo padeciese y resucitase de entre los muertos''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74076, 'spa', 'Encontrarse por casualidad', 'Hechos 17:17 menciona que Pablo razonaba con quienes ''se encontraban presentes'' (παρατυγχάνοντας) en la plaza ateniense. Las traducciones enfatizan los encuentros casuales. Pablo no esperaba audiencias formales, sino que abordaba a quienes la providencia ponía en su camino. El ágora se transformó en campo misionero donde los transeúntes ocasionales se encontraban con la verdad del evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74077, 'spa', 'Momentáneo y pasajero', 'Segunda Corintios 4:17 llama a la tribulación presente ''momentánea'' (παραυτίκα) y leve en comparación con la gloria eterna. La estrategia retórica de Pablo relativiza el sufrimiento al contraponer la escala temporal con la eterna. Lo que se siente aplastante e interminable se vuelve leve y breve cuando se mide contra la eternidad, transformando la perspectiva del creyente sobre la adversidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74078, 'spa', 'Quitar o arrastrar', 'Llevar aparte, remover o arrastrar, por acción deliberada (quitar algo no deseado) o por fuerza externa (ser desviado del rumbo). Marcos 14:36 y Lucas 22:42 lo usan en la oración de Jesús para que se quite la copa. Hebreos 13:9 y Judas 1:12 expresan lo pasivo: ser arrastrado por falsas enseñanzas o zarandeado como nubes vacías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74079, 'spa', 'Desvarío retórico', 'Segunda Corintios 11:23 presenta a Pablo hablando ''como fuera de sí'' (παραφρονῶν) al jactarse de sus sufrimientos. Las traducciones captan la aparente irracionalidad. Pablo reconoce lo absurdo que suena su alarde: ¿quién presenta golpizas, naufragios y hambre como credenciales? Pero en la lógica del ministerio cristiano, la debilidad se convierte en la prueba más elocuente de autenticidad apostólica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74080, 'spa', 'Locura moral', 'Segunda Pedro 2:16 llama a la desobediencia de Balaam ''locura'' (παραφρονίαν). El absurdo narrativo subraya la demencia moral: cuando un profeta necesita que una burra lo haga entrar en razón, su pecado ha creado un trastorno más profundo que cualquier diagnóstico. La codicia convierte a los sabios en necios y a los profetas en seres más irracionales que los animales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74081, 'spa', 'Invernar', 'Pasar la temporada invernal en un lugar determinado, generalmente porque la navegación marítima resultaba imposible durante los meses fríos. Las tradiciones de traducción emplean un término estacional específico — invernar, hiverner — en vez de un genérico ''quedarse''. Hechos 27:12 refleja la urgencia de hallar puerto seguro; 1 Corintios 16:6 y Tito 3:12 lo usan en planes pastorales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74082, 'spa', 'Invernada marítima', 'Hechos 27:12 menciona que Buenos Puertos no era apto ''para invernar'' (παραχειμασίαν). Las limitaciones del puerto impulsaron la decisión de navegar hacia Fénix a pesar de lo avanzado de la estación, con consecuencias catastróficas. El detalle de Lucas resalta cómo las preocupaciones prácticas, como encontrar refugio invernal adecuado, entrelazaban logística humana con providencia divina en la narrativa del viaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74083, 'spa', 'Adverbio que indica que algo sucede al instante, en el acto, sin intervalo algun', 'Adverbio que indica que algo sucede al instante, en el acto, sin intervalo alguno de demora. Lucas lo emplea de modo característico para subrayar la inmediatez de la acción divina: el paralítico se levanta al instante (Lc 5:25), la mujer encorvada se endereza de inmediato (Lc 13:13), el ciego recobra la vista al momento (Lc 18:43), la suegra de Pedro es sanada en el acto (Lc 4:39). También marca juicios divinos repentinos en Hechos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74084, 'spa', 'Leopardo apocalíptico', 'Apocalipsis 13:2 describe a la bestia como semejante a ''un leopardo'' (παρδάλει). Las traducciones (español ''leopardo'', francés ''Panther'', alemán ''Panther'') identifican al felino manchado. La visión apocalíptica de Juan combina rasgos de las bestias de Daniel: el cuerpo del leopardo por su velocidad y sigilo, las patas de oso por su fuerza aplastante, y la boca del león por su autoridad devoradora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74085, 'spa', 'Estar presente en un lugar o situación, describiendo un estado continuo más que ', 'Estar presente en un lugar o situación, describiendo un estado continuo más que el momento de llegada. Cubre la gran mayoría de las ocurrencias: la multitud presente durante la enseñanza de Jesús (Lc 13:1), la casa de Cornelio reunida ante Dios (Hch 10:33), y el contraste de Pablo entre su presencia y su ausencia (2 Cor 10:2, 11; 13:2, 10; Gál 4:18, 20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74089, 'spa', 'Llegar o hacerse presente, enfatizando la transición de la ausencia a la presenc', 'Llegar o hacerse presente, enfatizando la transición de la ausencia a la presencia. Jesús «está aquí» llamando a María junto a la tumba de Lázaro (Jn 11:28); Jesús se dirige a Judas en el arresto: «Amigo, ¿a qué vienes?» (Mt 26:50); la delegación tiria «se presentó» ante Herodes buscando la paz (Hch 12:20); Pablo «llegó» ante Festo (Hch 10:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74090, 'spa', 'Uso participial sustantivado que significa «las cosas presentes» o «lo que está ', 'Uso participial sustantivado que significa «las cosas presentes» o «lo que está a la mano»: posesiones o circunstancias actuales. Hebreos 13:5 exhorta a los creyentes a contentarse con τὰ παρόντα, «las cosas presentes», una instrucción moral sobre la suficiencia material que transforma la presencia espacial en una categoría filosófica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74100, 'spa', 'Introducir encubiertamente', '2 Pedro 2:1 advierte que los falsos maestros ''introducirán secretamente'' (παρεισάξουσιν) herejías destructivas. Las traducciones (español ''introducirán'', alemán ''einfuehren'') resaltan la introducción encubierta. La dimensión de sigilo del verbo es esencial: no son maestros honestos que presenten alternativas para examen abierto, sino infiltradores que meten el error de contrabando en la comunidad de fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74101, 'spa', 'Infiltrado encubiertamente', 'Gálatas 2:4 habla de falsos hermanos ''infiltrados'' (παρεισάκτους) que se introdujeron para espiar la libertad cristiana. Las traducciones (español ''infiltrados'', francés retiene la forma griega) enfatizan la infiltración encubierta. El lenguaje militar de Pablo (espiar, para esclavizar) trata la situación como guerra espiritual: no son opositores teológicos honestos sino saboteadores dentro de la comunidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74102, 'spa', 'Infiltrarse sigilosamente', 'Judas 4 advierte que ciertas personas ''se han colado'' (παρεισδύησαν) inadvertidamente. Las traducciones (español ''se-infiltraron'', francés ''se-sont-glissés'', alemán ''eingeschlichen-haben-sich'') enfatizan la infiltración furtiva. La alarma de Judas refleja el descubrimiento de agentes enemigos ya integrados en la comunidad, no un peligro futuro teórico sino un compromiso presente que exige respuesta pastoral urgente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74104, 'spa', 'Aportar con diligencia', '2 Pedro 1:5 exhorta a los creyentes a que, ''habiendo aportado'' (παρεισενέγκαντες) toda diligencia, suplementen la fe con virtud. Las traducciones (español ''habiendo-aportado'', alemán ''hinzufuegen'') captan la acción de suplementar. La construcción participial muestra la base del mandato: precisamente porque has aplicado diligencia, ahora añade a la fe esta secuencia de virtudes que confirman tu vocación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74105, 'spa', 'Excepción o exclusión', 'Las glosas multilingües capturan uniformemente el concepto de excepción: en español «excepto», «demás cosas»; en francés «excepté»; en alemán «ausser». El léxico lo define como «además de o excepto algo, con genitivo». Mt 5:32 permite el divorcio solo «excepto» por fornicación. Hch 26:29 excluye las cadenas de Pablo de su deseo para Agripa. 2 Co 11:28 lo usa como «además de» las circunstancias externas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74106, 'spa', 'Cuartel, guarnición militar — el cuartel militar romano, específicamente la Fort', 'Cuartel, guarnición militar — el cuartel militar romano, específicamente la Fortaleza Antonia en Jerusalén donde Pablo fue retenido bajo custodia protectora. Las seis apariciones se concentran en Hechos 21-23, formando una unidad narrativa: los soldados llevan a Pablo al cuartel (Hch 21:34), Pablo habla en la entrada (21:37), es conducido al interior para interrogatorio (22:24) y retirado por seguridad (23:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74107, 'spa', 'Campamento, ejército — campamento, formación militar o hueste en sentido amplio,', 'Campamento, ejército — campamento, formación militar o hueste en sentido amplio, no un edificio fijo sino una formación temporal o conceptual. En Heb 13:11 y 13:13 evoca el campamento israelita del desierto con sus límites de pureza, ya que Jesús «padeció fuera del campamento». En Heb 11:34 se refiere a ejércitos extranjeros («pusieron en fuga a ejércitos extranjeros»), y en Ap 20:9 describe «el campamento de los santos» sitiado por las naciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74111, 'spa', 'Importunar o agobiar', 'En Hechos 15:19 Santiago declara que no se debe ''molestar'' (παρενοχλεῖν) a los gentiles que se vuelven a Dios. La evidencia de traducción (inglés ''to-trouble'', español ''molestar'', francés ''importuner'') subraya la acción de agobiar. La elección verbal de Santiago es retóricamente poderosa: imponer la circuncisión y la ley de Moisés importunaría a los conversos gentiles en vez de darles la bienvenida. El evangelio elimina barreras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74112, 'spa', 'Forastero o peregrino', 'La evidencia multilingüe subraya la condición de extranjería temporal: en español «forasteros», «peregrinos»; en alemán «Fremdlinge». El léxico lo define como «que reside temporalmente en lugar ajeno», frecuentemente sustantivado. Heb 11:13 describe a los fieles como «extranjeros y peregrinos en la tierra». 1 Pe 1:1 se dirige a los «expatriados de la dispersión». 1 Pe 2:11 exhorta a los creyentes como «forasteros y peregrinos» a apartarse de las pasiones carnales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74113, 'spa', 'Pasar, llegar a su fin', 'Pasar, llegar a su fin. El sentido escatológico y temporal: pasar, acabarse, dejar de existir. Es el uso más frecuente (17 de 30 apariciones), concentrado en el discurso apocalíptico de Jesús. El cielo y la tierra «pasarán» (Mt 24:35; Mr 13:31; Lc 21:33), esta generación no «pasará» hasta que todo se cumpla (Mt 24:34; Mr 13:30), y el tiempo mismo «ha pasado» (Mt 14:15; Hch 27:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74115, 'spa', 'Pasar de largo físicamente', 'Pasar de largo físicamente. Tránsito físico: moverse junto a un lugar o persona en el espacio, pasar de largo sin detenerse. Presente en contextos narrativos —Jesús pasando por el camino (Mr 6:48), la ruta pasando por Misia (Hch 16:8), o nadie pudiendo pasar junto a los endemoniados (Mt 8:28). El participio «pasando» en Lc 18:37 describe el avance de Jesús por la calle.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74116, 'spa', 'Ser quitado, pasar de', 'Ser quitado, pasar de. Ser removido o evitado: que una prueba, copa o carga sea apartada. Las oraciones de Getsemaní son definitivas —«pase de mí esta copa» (Mt 26:39, 42)—, donde Jesús pide no que la copa se traslade físicamente sino que la experiencia sea evitada por completo. Lc 16:17 extiende esto a la imposibilidad de que la más mínima tilde de la Ley «pase.»');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74119, 'spa', 'Transgredir, desatender', 'Transgredir, desatender. Transgredir, pasar por alto un mandamiento u obligación. En Lc 11:42 Jesús reprende a los fariseos por diezmar las hierbas mientras «pasan por alto» la justicia y el amor de Dios. En Lc 15:29 el hijo mayor protesta que nunca «transgredió» el mandato de su padre. La metáfora es vívida: caminar junto a una obligación sin reconocerla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74121, 'spa', 'Venir, acercarse', 'Venir, acercarse. Avanzar, acercarse, llegar: una sorprendente inversión semántica donde el verbo de ''pasar'' significa venir en vez de irse. En Lc 12:37 el amo «viene» a servir a sus siervos vigilantes; en Lc 17:7 un siervo «entra» del campo. Hch 24:7 (en algunos manuscritos) usa el participio del comandante romano Lisias «llegando» con fuerza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74132, 'spa', 'Tolerancia divina temporal', 'Romanos 3:25 habla del ''pasar por alto'' (πάρεσιν) de los pecados previamente cometidos. La evidencia de traducción (inglés ''passing-over'', español ''pasar-por-alto'', alemán ''Vorbeigehen'') capta la paciencia de Dios. Pablo distingue con precisión: Dios no ignoró ni borró los pecados anteriores a la cruz, sino que suspendió el juicio hasta la muerte expiatoria de Cristo. La cruz demuestra tanto la justicia como la misericordia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74133, 'spa', 'Causar o provocar algo negativo', 'Causar o provocar algo negativo: molestia, dificultad o contrariedad. Esta es la expresión idiomática παρέχειν κόπον (''causar molestia''), destacada en los Evangelios sinópticos. En Mt 26:10 y Mr 14:6, Jesús pregunta: ''¿Por qué le causáis molestia?''. Lc 11:7 y 18:5 la usan para peticionarios insistentes que crean incomodidad. Gá 6:17 presenta a Pablo declarando ''que nadie me cause más molestias''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74134, 'spa', 'Proveer, suministrar, conceder o dar algo beneficioso', 'Proveer, suministrar, conceder o dar algo beneficioso. El centurión es ''digno'' de recibir lo que pide (Lc 7:4); una esclava ''proporcionaba'' mucha ganancia a sus amos mediante la adivinación (Hch 16:16); Dios ha ''dado'' prueba del juicio al resucitar a Jesús (Hch 17:31). Pablo ordena a los amos ''proveer'' lo justo y equitativo (Col 4:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74135, 'spa', 'Presentar, ofrecer o mostrar algo a otra persona, a menudo con un carácter demos', 'Presentar, ofrecer o mostrar algo a otra persona, a menudo con un carácter demostrativo o formal. Lc 6:29 instruye: ''ofrece también la otra mejilla''; Hch 28:2 describe a los malteses ''mostrando'' una hospitalidad extraordinaria; Tit 2:7 exhorta a Tito a ''presentarse como ejemplo'' de buenas obras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74142, 'spa', 'Mantener o guardar un estado, específicamente en la expresión idiomática παρέχει', 'Mantener o guardar un estado, específicamente en la expresión idiomática παρέχειν ἡσυχίαν, ''guardar silencio''. Hch 22:2 relata que cuando Pablo habló en arameo, la multitud ''guardó'' un silencio aún mayor. La aparición única de esta colocación en el NT la marca como un uso idiomático especializado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74147, 'spa', 'Consuelo tangible', 'Colosenses 4:11 describe a colaboradores judíos cristianos que fueron ''un consuelo'' (παρηγορία) para Pablo. La evidencia de traducción (inglés ''comfort'', español ''consuelo'', francés y alemán conservan formas del término griego) enfatiza la consolación. El aprecio de Pablo revela el costo emocional del trabajo apostólico y el papel vital de la comunidad solidaria. Estos hombres lo fortalecieron no solo con ayuda práctica sino con presencia reconfortante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74148, 'spa', 'Estado virginal prenupcial', 'Lucas 2:36 describe a Ana viviendo con su marido siete años ''desde su virginidad'' (παρθενίας). La evidencia de traducción (inglés ''virginity'', español ''virginidad'', francés ''virginité'') marca su estado de soltería previo al matrimonio. El detalle establece la biografía de Ana: casada joven, viuda tras siete años, luego décadas de servicio en el templo. La frase ''desde su virginidad'' enfatiza que entró al matrimonio en pureza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74149, 'spa', 'Persona, normalmente mujer joven, que no ha tenido relaciones sexuales; una donc', 'Persona, normalmente mujer joven, que no ha tenido relaciones sexuales; una doncella. Central en los relatos del nacimiento, donde María es identificada dos veces como παρθένος (Mt 1:23; Lc 1:27), cumpliendo la profecía de Isaías y estableciendo la concepción virginal. En la parábola de las diez vírgenes (Mt 25:1-11), el término designa a las acompañantes de la boda cuya preparación o falta de ella simboliza la disposición espiritual. Pablo lo emplea tanto literalmente, para mujeres solteras que eligen el celibato (1 Co 7:25-34), como figuradamente, para la iglesia presentada como virgen pura ante Cristo (2 Co 11:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74155, 'spa', 'Pueblo de Partia', 'Hechos 2:9 enumera a los ''partos'' (Πάρθοι) entre quienes oyeron a los apóstoles en Pentecostés. La evidencia de traducción (inglés ''Parthoi'', español ''Párthoi'', francés ''Parthe'') conserva la designación étnica. Al listar a los partos primero (geográficamente los más orientales), Lucas inicia su catálogo de naciones con el máximo alcance, desde el rival oriental de Roma hasta diversos pueblos mediterráneos. El milagro lingüístico anuncia la universalidad del evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74157, 'spa', 'Estar al lado, estar presente — sentido intransitivo estativo', 'Estar al lado, estar presente — sentido intransitivo estativo: estar de pie junto a alguien o hallarse presente. Los que estaban junto a Jesús durante su juicio y crucifixión «estaban de pie» (Marcos 14:47, 69, 70; 15:35, 39). La proximidad física implícita con frecuencia tiene significado narrativo, situando a los testigos en momentos cruciales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74158, 'spa', 'Presentar, ofrecer, entregar — sentido transitivo causativo', 'Presentar, ofrecer, entregar — sentido transitivo causativo: presentar, ofrecer o entregar a alguien o algo ante otro, especialmente ante Dios. Lucas 2:22 registra a Jesús siendo «presentado» en el templo; Romanos 6:13 exhorta a los creyentes a «presentar vuestros miembros como instrumentos de justicia». El español «presentar» refleja el carácter formal y dedicatorio de este vocabulario de ofrenda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74165, 'spa', 'Asistir, apoyar — estar junto a alguien en un rol de apoyo, brindando asistencia', 'Asistir, apoyar — estar junto a alguien en un rol de apoyo, brindando asistencia. Pablo elogia a Febe, quien «asistió» a muchos (Romanos 16:2), y en 2 Timoteo 4:17 el Señor «estuvo al lado» de Pablo en su juicio. El paso de la mera presencia física al apoyo activo distingue este sentido del sentido 2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74169, 'spa', 'Proveer, suministrar, preparar — proporcionar o disponer algo para su uso', 'Proveer, suministrar, preparar — proporcionar o disponer algo para su uso. En Mateo 26:53 Jesús podría pedir al Padre que «proveyera» doce legiones de ángeles; en Hechos 23:24, Lisias ordena que se «provean» cabalgaduras. El contexto militar y logístico revela un significado preparatorio distinto del «presentar» cultual del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74173, 'spa', 'Probar, demostrar — uso forense', 'Probar, demostrar — uso forense: demostrar o probar algo. En Hechos 24:13, los acusadores de Pablo «no pueden probar» sus cargos. Esto extiende el sentido de «poner ante la mente» atestiguado en el griego clásico, pasando de la presentación física a la demostración probatoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74174, 'spa', 'Llegar, presentarse (del tiempo) — del tiempo o la cosecha que llega o se presen', 'Llegar, presentarse (del tiempo) — del tiempo o la cosecha que llega o se presenta. Marcos 4:29 dice que cuando el grano «ha llegado» (está maduro), se envía la hoz. Este uso impersonal del verbo refleja el sentido clásico de un momento o condición que se presenta por sí mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74175, 'spa', 'Comparecer, presentarse ante — estar de pie ante un juez o autoridad divina para', 'Comparecer, presentarse ante — estar de pie ante un juez o autoridad divina para ser examinado. Hechos 27:24 promete a Pablo que debe «comparecer» ante el César; Romanos 14:10 advierte que todos «compareceremos» ante el tribunal. Este sentido de comparecencia judicial une la posición física con la rendición formal de cuentas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74185, 'spa', 'Nombre propio', 'Hechos 6:5 menciona a ''Parmenas'' (Παρμενᾶν) como uno de los siete. La evidencia multilingüe simplemente transliteran el nombre propio. Más allá de esta única mención no sabemos nada de su servicio, pero su selección atestigua un carácter lleno del Espíritu y sabiduría. Los siete se convirtieron en modelo del ministerio diaconal, y Parmenas ocupa un lugar honroso en esa tradición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74186, 'spa', 'Tránsito o paso', '1 Corintios 16:7 presenta a Pablo diciendo que no quiere verlos meramente ''de paso'' (πάροδον). Las traducciones resaltan el carácter breve y transitorio del encuentro. Pablo contrasta un ministerio superficial de paso rápido con una presencia prolongada y significativa. La relación auténtica requiere tiempo; el cuidado apostólico implica quedarse lo suficiente para conocer y fortalecer verdaderamente a la comunidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74189, 'spa', 'Forastero residente', 'Forastero o extranjero residente que habita en tierra ajena sin plenos derechos de ciudadanía. La raíz παρά + οἶκος (junto a la casa) evoca a quien vive al margen. Hechos 7:6 y 7:29 lo usan para Israel en Egipto y Moisés en Madián. Efesios 2:19 lo transforma teológicamente y 1 Pedro 2:11 lo reivindica como identidad espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74190, 'spa', 'Dicho figurado', 'Proverbio, dicho figurado o parábola: forma de discurso indirecta y metafórica que requiere comprensión profunda. A diferencia de παραβολή (sinópticos), Juan emplea παροιμία para el estilo figurado de Jesús. En Juan 10:6 desconcertó a los fariseos; Juan 16:25 contrasta el lenguaje figurado presente con la claridad futura. Segunda de Pedro 2:22 lo usa como proverbio literal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74192, 'spa', 'Pasado o pretérito', 'Hechos 14:16 habla de Dios permitiendo a las naciones andar en sus caminos en generaciones ''pasadas'' (παρῳχημέναις). La distinción temporal de Pablo tiene una carga teológica profunda: la tolerancia divina hacia la ignorancia gentil caracterizó las épocas anteriores, pero la venida de Cristo crea una situación nueva. La llegada del evangelio transforma las expectativas para todos los pueblos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74193, 'spa', 'Asemejarse o parecerse', 'Mateo 23:27 presenta a Jesús diciendo ''os parecéis'' (παρομοιάζετε) a sepulcros blanqueados. La fuerza del símil depende del contraste: las tumbas encaladas antes de la Pascua relucen brillantemente pero contienen muerte e impureza ritual. De igual modo, los líderes religiosos pueden exhibir una piedad impresionante mientras albergan corrupción interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74198, 'spa', 'Enojo o ira', 'Efesios 4:26 ordena no dejar que el sol se ponga sobre vuestro ''enojo'' (παροργισμῷ). La instrucción de Pablo equilibra realismo —la ira ocurre— con disciplina: no dejes que se enconre. El plazo de la puesta del sol crea urgencia: reconcíliate antes de que anochezca, no duermas con la ira, resuélvela antes de que se endurezca y se convierta en amargura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74199, 'spa', 'Incitar, instigar', 'Hechos 13:50 relata que los judíos «incitaron» (παρώτρυναν) a mujeres prominentes y hombres principales contra Pablo. La evidencia multilingüe (español «incitaron», francés «exciter») subraya la acción de azuzar. Lucas revela así la mecánica de la persecución: los opositores movilizan a las élites sociales que tienen poder para expulsar a los considerados problemáticos. La estrategia tiene éxito y Pablo y Bernabé son desterrados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74200, 'spa', 'La venida o llegada de una persona, especialmente el advenimiento escatológico d', 'La venida o llegada de una persona, especialmente el advenimiento escatológico de Cristo al final de los tiempos, pero también usada para la llegada de personas como Pablo, Estéfanas o Tito. El discurso del Olivete de Jesús (Mt 24:3, 27, 37, 39) y la enseñanza de Pablo sobre la resurrección (1 Cor 15:23) establecen este como el uso dominante en el NT. «Venida» en español capta con precisión el evento de llegar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74201, 'spa', 'El estado de estar físicamente presente en un lugar', 'El estado de estar físicamente presente en un lugar: la presencia personal o la apariencia de alguien en contraste con su ausencia. Pablo admite que su presencia corporal es débil (2 Cor 10:10), y Filipenses 2:12 contrasta «en mi presencia» con «en mi ausencia», mostrando que παρουσία aquí significa simplemente «estar allí». Filipenses 1:26 la usa para la visita anticipada de Pablo, fusionando la llegada con la presencia continuada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74205, 'spa', 'Denuedo, confianza — valentía interior, confianza y coraje sin temor, especialme', 'Denuedo, confianza — valentía interior, confianza y coraje sin temor, especialmente al hablar o al acercarse a Dios. Es el sentido dominante del Nuevo Testamento (22 veces), presente en Hechos, Hebreos y las epístolas paulinas. La παρρησία de Pedro y Juan asombra al Sanedrín en Hechos 4:13, y la iglesia primitiva ora pidiendo denuedo para proclamar la palabra (Hechos 4:29, 31). Hebreos 4:16 invita a acercarse al trono de la gracia «con confianza».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74206, 'spa', 'Abiertamente, públicamente, con claridad — franqueza, carácter público o clarida', 'Abiertamente, públicamente, con claridad — franqueza, carácter público o claridad en el hablar y el actuar, usado adverbialmente (a menudo en dativo o con «en»). Concentrado en el Evangelio de Juan (9 veces), donde contrasta con hablar en secreto o en figuras. Los hermanos de Jesús lo desafían a actuar ἐν παρρησίᾳ en Juan 7:4, y los judíos le exigen que hable «con claridad» en Juan 10:24.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74212, 'spa', 'Hablar con denuedo', 'Hablar con libertad audaz y confianza valerosa, especialmente al proclamar el evangelio o defender la fe públicamente frente a la oposición. Las nueve apariciones neotestamentarias se encuentran en Hechos y las cartas paulinas en contextos de predicación misionera bajo presión (Hch 9:27-28, 13:46, 14:3, 18:26, 19:8). La forma deponente media subraya el compromiso personal del hablante en el acto intrépido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74219, 'spa', 'todos (colectivo plural)', 'Plural colectivo: ''todos'' tomados en conjunto como totalidad, el sentido dominante con 616 apariciones. Se refiere a la integridad de un grupo visto como un todo: ''todos los principales sacerdotes'' (Mt 2:4), ''toda la region'' (Mt 4:24), ''todos los enfermos'' (Mt 4:24). El enfasis recae en la completitud mas que en la distribucion individual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74220, 'spa', 'cada, todo (distributivo)', 'Singular distributivo: ''cada'' o ''todo'' miembro de una clase individualmente, con 227 apariciones. Con sustantivos en singular, πᾶς pasa de la totalidad grupal al alcance individuo por individuo: ''toda ciudad'' (Mt 4:23), ''todo el que se enoja'' (Mt 5:22), ''todo buen arbol'' (Mt 7:17). El espanol todo/toda capta bien este marco distributivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74221, 'spa', 'todo, entero (totalidad singular)', 'Con sustantivos singulares articulados: ''todo/a,'' ''entero/a,'' con 187 apariciones donde πᾶς modifica un sustantivo singular con articulo para indicar la totalidad de una sola entidad. ''Toda la ciudad'' (Mt 8:34), ''toda la multitud'' (Mt 13:2), ''toda Judea'' (Mt 3:5). Se distingue del sentido colectivo plural porque aqui una unica entidad se contempla en su integridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74223, 'spa', 'todas las cosas (sustantivo)', 'Neutro sustantivado: ''todas las cosas'' o ''todo,'' con 211 apariciones donde πᾶς funciona sin sustantivo modificado (a menudo como τὰ πάντα o πάντα), refiriendose a la totalidad de las cosas o la realidad. Teologicamente decisivo en pasajes como Col 1:16 (''todas las cosas fueron creadas por medio de el'') y 1 Cor 15:27 (''todo lo sujeto bajo sus pies'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74238, 'spa', 'siempre (temporal)', 'Adverbial temporal: ''siempre,'' ''en todo tiempo,'' ''continuamente,'' con 9 apariciones en expresiones fijas como διὰ παντός (''por todo [tiempo]''). En Mt 18:10 los angeles ''siempre'' contemplan el rostro del Padre; en Lc 24:53 los discipulos estaban ''continuamente'' en el templo; en Hch 2:25 David tenia al Senor ''siempre'' delante de si.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74261, 'spa', 'La Pascua en su sentido integral', 'La Pascua en su sentido integral: la fiesta judía anual de la liberación (Éx 12), la cena pascual y el cordero sacrificial. Las narraciones sinópticas de la Pasión entrelazan los tres referentes cuando Jesús instruye a sus discípulos a preparar la cena de Pascua (Mt 26:17-19; Mc 14:12-16; Lc 22:7-13), mientras que la cronología de Juan sitúa la crucifixión a la hora del sacrificio del cordero (Jn 18:28). La declaración de Pablo, «Cristo, nuestra Pascua, ha sido sacrificado» (1 Cor 5:7), cristaliza la transferencia tipológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74263, 'spa', 'Padecer, sufrir — sufrir, soportar dolor o adversidad', 'Padecer, sufrir — sufrir, soportar dolor o adversidad. En los anuncios de la pasión (Mateo 16:21; Marcos 8:31; Lucas 9:22), πάσχω se convierte prácticamente en un término técnico para el sufrimiento señalado de Cristo. Se extiende a los creyentes que comparten los padecimientos de Cristo (Filipenses 1:29; 1 Pedro 4:1) y al sufrimiento ordinario, como el muchacho atormentado de Mateo 17:15. El español «padecer» capta con fuerza la dimensión tanto redentora como experiencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74281, 'spa', 'Puerto de Licia', 'Hechos 21:1 menciona «Pátara» (Πάταρα) como escala de Pablo. Las traducciones conservan el topónimo (español «Pátara», francés «Patara»). Este puerto licio proporcionó a Pablo la conexión necesaria para el tramo final hacia Fenicia y Jerusalén. La precisión geográfica de Hechos refleja la atención de Lucas a la logística de los viajes, pues la misión apostólica dependía de las rutas marítimas del Mediterráneo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74282, 'spa', 'Golpear, herir — asestar un golpe, ya sea con arma, con la mano o por intervenci', 'Golpear, herir — asestar un golpe, ya sea con arma, con la mano o por intervención divina; golpear, herir o atacar. Las diez apariciones son variantes flexivas de un solo significado: el golpe de espada de Pedro (Mt 26:51; Lc 22:50), Moisés golpeando al egipcio (Hch 7:24), un ángel golpeando a Pedro para despertarlo (Hch 12:7), un ángel hiriendo a Herodes de muerte (Hch 12:23), la cita de Zacarías sobre herir al pastor (Mt 26:31), y el juicio escatológico en Apocalipsis (11:6; 19:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74288, 'spa', 'Pisar, pisotear', 'Pisar, pisotear o aplastar bajo los pies, literal o metafóricamente, para expresar conquista, profanación o juicio divino. En Lucas 10:19, los creyentes reciben autoridad para «pisar serpientes y escorpiones». Lucas 21:24 lo emplea para la profanación gentil de Jerusalén. Apocalipsis recurre al lagar pisado (Ap 14:20; 19:15) como expresión del juicio de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74289, 'spa', 'padre o Padre divino', 'Sentido amplio que cubre tanto al padre humano como a Dios en cuanto Padre, abarcando la gran mayoría de las apariciones. Incluye la invocación de Jesús a Dios como Padre (Mt 6:9; Jn 17:1), padres humanos en genealogías y narraciones (Mt 3:9; Lc 1:59), y la teología relacional Padre-Hijo de Pablo y Juan. La distinción entre lo divino y lo humano reside en el contexto, no en la forma léxica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74293, 'spa', 'antepasado, patriarca', 'Un antepasado o progenitor en una línea genealógica o pactal, como cuando Pablo habla de Abraham como «nuestro padre» (Ro 4:1) o se refiere a la herencia patriarcal de Israel (Ro 9:5; 11:28; 15:8). Aunque con solo cuatro apariciones, este sentido lleva gran peso teológico en las discusiones sobre la continuidad del pacto y la identidad de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74296, 'spa', 'padres (ambos progenitores)', 'Usado en plural para significar «padres» —padre y madre juntos—, como en Heb 11:23 donde los padres de Moisés lo escondieron. La evidencia multilingüe es decisiva: hindi माता-पिता («madre-padre»), coreano 부모 («padres») y suajili wazazi («padres») confirman el significado inclusivo. Una attestación única pero importante que muestra la flexibilidad semántica de πατήρ.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74302, 'spa', 'Isla del exilio', 'Apocalipsis 1:9 sitúa a Juan en la isla llamada «Patmos» (Πάτμῳ). Las traducciones preservan el nombre (español «Pátmos», francés «Patmos»). El exilio de Juan a esta roca árida pretendía silenciar su testimonio, pero el aislamiento se convirtió en cuna de la revelación. La geografía importa: apartado de las iglesias que pastoreaba, Juan recibió visiones destinadas a la iglesia universal. El castigo romano posicionó al profeta para una visión cósmica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74303, 'spa', 'Parricida', 'Primera Timoteo 1:9 incluye a los «parricidas» (πατρολῴαις) en el catálogo de vicios de Pablo. Las traducciones (español «parricidas», alemán «Vaterschlaeger») identifican a quienes agreden a sus padres. La lógica del catálogo agrupa crímenes similares: homicidas y parricidas (violencia), inmorales (pecado sexual), traficantes de esclavos (explotación de personas), mentirosos y perjuros (falsedad). El parricidio representa la subversión más radical del orden familiar establecido por Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74304, 'spa', 'Familia o linaje', 'Las glosas multilingües resaltan los conceptos de familia y linaje: en español «familia», «familias»; en francés «famille»; en alemán «Geschlecht». El léxico señala «linaje, descendencia, especialmente por vía paterna», incluyendo los significados de clan y familia. Lc 2:4 lo usa para el linaje davídico de José. Hch 3:25 cita Génesis respecto a todas las «familias» de la tierra. Ef 3:15 lo aplica a toda familia que recibe su nombre del Padre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74305, 'spa', 'Patriarca', 'Padre fundador o progenitor principal de un linaje, tribu o nación, especialmente uno de los venerados ancestros de Israel. Conlleva autoridad genealógica y espiritual. Hechos 2:29 lo aplica a David, Hechos 7:8-9 a los doce hijos de Jacob y Hebreos 7:4 a Abraham. El cognado «patriarca» refleja la universalidad del concepto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74306, 'spa', 'Paterno, ancestral', 'Se refiere a lo heredado del padre o de los antepasados, especialmente tradiciones y costumbres transmitidas de generación en generación. El uso de Pablo en Gálatas subraya su antigua devoción a las tradiciones judías ancestrales antes de su encuentro con Cristo, mostrando la herencia cultural y religiosa que en otro tiempo defendió con ardor y que la revelación divina transformó radicalmente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74307, 'spa', 'Patria, tierra natal', 'Lugar de origen, pueblo natal o patria ancestral. En los Evangelios se refiere específicamente al pueblo de Jesús, Nazaret, donde se aplica el proverbio «no hay profeta sin honra en su propia patria» ante su rechazo (Mt 13:54-57, Mr 6:1-4, Lc 4:23-24, Jn 4:44). En Hebreos 11:14, el término adquiere un registro trascendente: los patriarcas se declaran peregrinos en la tierra, buscando una patria celestial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74310, 'spa', 'Nombre propio cristiano', 'Nombre personal de un cristiano en Roma. Pablo incluye a Patrobas en una lista de saludos (Rom 16:14) junto con Hermas, Filólogo, Julia y otros, lo que sugiere que formaba parte de una iglesia doméstica o comunidad cristiana en la capital. La brevedad de la mención refleja el patrón paulino de reconocer a muchos creyentes por nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74311, 'spa', 'Heredado de antepasados', 'Describe tradiciones, costumbres o modos de vida transmitidos por las generaciones anteriores. En 1 Pedro, el término caracteriza las observancias religiosas vacías y los patrones morales heredados de ancestros paganos, que resultaron inútiles para la salvación. La idea central es la transmisión generacional que el vocablo enfatiza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74312, 'spa', 'Ancestral o paterno', 'La evidencia multilingüe subraya la naturaleza heredada y ancestral: en español «de los padres»; en francés «paternel»; en alemán se conservan las formas griegas πατρῴοις/πατρῴου/πατρῴῳ. El léxico lo define como «de o proveniente del padre, recibido o heredado de él», con acepciones que incluyen «patria», «patrimonio» y «amigo hereditario». Las tres apariciones en el NT (Hch 22:3; 24:14; 28:17) se refieren a la ley, la fe y las costumbres recibidas de los antepasados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74313, 'spa', 'Pablo (apóstol)', 'El nombre propio Παῦλος, referido principalmente al apóstol Pablo (antes Saulo de Tarso), el misionero principal al mundo gentil y autor de la mayoría de las epístolas neotestamentarias. También usado una vez para Sergio Paulo, procónsul romano de Chipre (Hch 13:7). Las 158 apariciones abarcan Hch 13–28 y los saludos epistolares (Ro 1:1, 1 Co 1:1, Gá 1:1). Las traducciones transliteran uniformemente: «Pablo», «Paul», «Paulus».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74316, 'spa', 'Sentido intransitivo en voz media', 'Sentido intransitivo en voz media: cesar, detenerse o dejar de realizar una actividad, donde el sujeto interrumpe su propia acción. Este sentido abrumadoramente dominante (14 apariciones) se presenta en contextos variados: la tempestad que cesa (Lc 8:24), Jesús que termina de enseñar (Lc 5:4; 11:1), los apóstoles que «no cesaban» de proclamar a Cristo (Hch 5:42; 6:13), y las oraciones incesantes de Pablo (Ef 1:16; Col 1:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74327, 'spa', 'Sentido causativo en voz activa', 'Sentido causativo en voz activa: refrenar o hacer que alguien o algo se detenga. Su única aparición neotestamentaria está en 1 Pedro 3:10, citando el Salmo 34:13 (LXX): «refrene su lengua del mal» (παυσάτω τὴν γλῶσσαν). Aquí el imperativo en voz activa presenta al sujeto como agente que debe contener activamente la lengua — una acción transitiva y causativa, distinta del simple cesar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74332, 'spa', 'Grillos o grilletes', 'Las glosas multilingües indican consistentemente ataduras para las piernas: en español «grillos», «con grillos»; en francés «entrave»; en alemán «Fessel». El léxico define πέδη como «grillo» (plural: grillos), señalando la conexión etimológica con los pies (πέζα) y mencionando usos para caballos, prisioneros e incluso ajorcas. Las tres apariciones en el NT (Mr 5:4 dos veces, Lc 8:29) describen los grilletes rotos por el endemoniado gadareno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74333, 'spa', 'Terreno llano', 'Se refiere a un terreno plano o nivelado, en oposición al relieve montañoso. La descripción de Lucas de Jesús de pie en un «lugar llano» sugiere una ubicación accesible donde las multitudes podían reunirse para escuchar su enseñanza. El término griego enfatiza la planicie del entorno geográfico, proporcionando un escenario concreto para el discurso de Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74334, 'spa', 'Viajar por tierra', 'Viajar por tierra a pie, particularmente en contraste con navegar por mar. La decisión de Pablo de ir por tierra a Asón mientras sus compañeros navegaban refleja una elección deliberada de ruta. El término subraya tanto el carácter peatonal del viaje como el contraste inherente entre tierra y mar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74336, 'spa', 'Obedecer a la autoridad', 'Obedecer o someterse a quienes ejercen autoridad: una obediencia estructurada y dirigida hacia el poder constituido, no mera conformidad pasiva. Hechos 5:29 establece la jerarquía: obedecer a Dios tiene precedencia sobre los gobernantes humanos. Hechos 5:32 liga esta obediencia al don del Espíritu, y Hechos 27:21 la extiende al consejo práctico de Pablo durante la travesía marítima.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74337, 'spa', 'Retóricamente persuasivo', 'Describe un discurso que es retóricamente persuasivo o convincente mediante habilidad humana. La negación de Pablo de que su predicación dependiera de «palabras persuasivas» subraya su rechazo de la oratoria sofisticada en favor de la sencillez investida por el Espíritu. Pablo subordina la elocuencia humana a la demostración del poder divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74338, 'spa', 'Ser persuadido, convencido', 'Ser persuadido, ganado o llegar a aceptar algo como verdadero: sentido pasivo/medio en que alguien recibe y cede ante la persuasión. La multitud estaba ''persuadida'' de que Juan era profeta (Lc 20:6); Gamaliel advierte al Sanedrín que dejaran a los apóstoles, y ellos fueron ''persuadidos'' por él (Hch 5:40). El español emplea ''persuadidos'' y ''fueron persuadidos'' para esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74339, 'spa', 'Persuadir, convencer activamente', 'Persuadir, convencer o ganar activamente a otra persona mediante argumento, razonamiento o apelación. Es el uso transitivo activo: Pablo y Bernabé ''persuadiendo'' a los convertidos a perseverar en la gracia (Hch 13:43); los principales sacerdotes ''persuadieron'' a las multitudes a pedir a Barrabás (Mt 27:20); opositores judíos de Antioquía ''persuadieron'' a las multitudes contra Pablo (Hch 14:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74340, 'spa', 'Confiar, tener confianza', 'Confiar, tener confianza en alguien o algo, típicamente expresado mediante el perfecto griego (πέποιθα, πέπεισμαι) que denota un estado asentado de confianza más que un acto de persuasión. Pablo escribe ''estoy confiado (πεποιθώς) en esto mismo'' (Fil 1:6); Jesús reprende a quienes ''confiaban en sí mismos creyéndose justos'' (Lc 18:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74347, 'spa', 'Obedecer, someterse', 'Obedecer, acatar o someterse a la autoridad: la extensión más extrema de la voz media/pasiva, donde ser persuadido se desliza hacia la sumisión. Hebreos 13:17 manda ''Obedeced (πείθεσθε) a vuestros pastores y sujetaos a ellos''; Santiago 3:3 usa el cognado para los caballos que obedecen el freno; Gálatas 5:7 pregunta ''¿quién os estorbó para no obedecer a la verdad?''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74375, 'spa', 'Experimentar hambre o carencia de alimento, desde la privación literal — Jesús a', 'Experimentar hambre o carencia de alimento, desde la privación literal — Jesús ayunando en el desierto (Mat 4:2), los discípulos arrancando espigas (Mat 12:1) — hasta el anhelo espiritual figurado en la Bienaventuranza (Mat 5:6). Las traducciones multilingües emplean la misma raíz para ambos registros, confirmando un sentido único que abarca el hambre física y metafórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74389, 'spa', 'Probar, examinar — poner a prueba o examinar', 'Probar, examinar — poner a prueba o examinar: someter a alguien o algo a prueba para evaluar su calidad, fidelidad o autenticidad. Dios prueba a Abraham (cf. Hebreos 11:17), y los opositores religiosos prueban a Jesús con preguntas capciosas (Mateo 16:1; 19:3; 22:35). El pasivo «ser probado» (Hebreos 2:18; 4:15) afirma que Jesús soportó toda la gama de la prueba humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74390, 'spa', 'Tentar, incitar al pecado — tentar o incitar hacia el pecado', 'Tentar, incitar al pecado — tentar o incitar hacia el pecado: solicitar a alguien a actuar contra la voluntad de Dios, con Satanás o el deseo maligno como fuerza motriz. La tentación en el desierto (Mateo 4:1, 3; Marcos 1:13; Lucas 4:2) es paradigmática. Pablo advierte que Satanás tienta por la falta de dominio propio (1 Corintios 7:5), y Santiago 1:13-14 distingue cuidadosamente la prueba divina de la incitación pecaminosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74395, 'spa', 'Intentar, procurar — intentar o esforzarse', 'Intentar, procurar — intentar o esforzarse: hacer un esfuerzo por lograr algo, sin connotación de incitación moral ni de evaluación de calidad. Saulo intentó unirse a los discípulos (Hechos 9:26), el Espíritu impidió a la compañía de Pablo ir a Bitinia (Hechos 16:7), y Tértulo acusó a Pablo de intentar profanar el templo (Hechos 24:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74413, 'spa', 'Prueba, tentación o experiencia que pone a prueba el carácter y la fe', 'Prueba, tentación o experiencia que pone a prueba el carácter y la fe. El término abarca desde la adversidad impuesta externamente (Luc 8:13, donde los creyentes de raíz superficial caen ''en tiempo de prueba'') hasta la seducción moral (Mat 6:13, ''no nos metas en tentación''). La advertencia de Jesús en Getsemaní (Mat 26:41; Mar 14:38) fusiona ambas dimensiones. El español distingue entre ''prueba'' y ''tentación'', pero el griego mantiene ambos matices en un solo vocablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74418, 'spa', 'Intentar o procurar', 'Hacer un intento o esforzarse por lograr algo, generalmente con empeño sostenido. El relato de Pablo describe cómo sus adversarios en el templo intentaban matarlo, lo que indica una acción deliberada y resuelta. Las glosas multilingües («were-attempting», «intentaban», «essayer») reflejan la naturaleza continua y esforzada del intento, subrayando la intención hostil de los adversarios de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74419, 'spa', 'Acto de persuadir', 'El acto o proceso de persuadir, o la influencia persuasiva misma. En Gálatas, Pablo identifica una persuasión que desvió a los creyentes de la libertad del evangelio, atribuyéndola a un origen humano y no divino. El término destaca el poder de la influencia y la convicción, que según advierte Pablo puede extraviar cuando no procede de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74421, 'spa', 'Decapitar con hacha', 'Ejecutar mediante decapitación, específicamente con un hacha. La visión de Juan en Apocalipsis honra a quienes fueron martirizados por su testimonio de Cristo, cuya decapitación ejemplifica la fidelidad suprema hasta la muerte. La evidencia interlingüística («having-been-beheaded», «decapitados», «Enthauptete») subraya uniformemente el método violento de ejecución, resaltando la realidad de la persecución y la recompensa de reinar con Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74422, 'spa', 'Numeral ordinal quinto', 'El número ordinal quinto, que designa el quinto elemento en una serie. En el Apocalipsis, estructura las series numeradas de juicios divinos: el quinto sello revela las almas de los mártires (Ap 6:9), la quinta trompeta abre el abismo (Ap 9:1), la quinta copa oscurece el reino de la bestia (Ap 16:10) y la quinta piedra fundacional de la Nueva Jerusalén es sardónice (Ap 21:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74423, 'spa', 'Enviar, despachar (activo)', 'Envío activo: despachar a una persona, mensaje o cosa hacia un destino con un propósito específico. Abarca la gran mayoría de las ocurrencias (76 de 79), incluyendo las parábolas de Jesús sobre siervos enviados (Lc 20:11-12), el envío del Espíritu (Jn 1:33) y las peticiones de enviar ayuda (Lc 16:24). El español ''que envió'' lo expresa con el verbo estándar de despacho.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74431, 'spa', 'Ser enviado (pasivo)', 'Comisionamiento pasivo: ser enviado o despachado, enfatizando el papel del agente como alguien bajo autoridad en lugar de actuar independientemente. Se encuentra en Lucas 4:26 (Elías ''fue enviado'' a la viuda de Sarepta), Lucas 7:10 (los ''enviados'' regresan y encuentran al siervo sano) y 1 Pedro 2:14 (gobernadores ''enviados'' por el emperador).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74443, 'spa', 'Pobre trabajador', 'Persona pobre que trabaja para ganarse el sustento, distinta del indigente o del rico. La cita paulina del salmo resalta el cuidado de Dios por quienes tienen medios modestos y trabajan con fidelidad. Las glosas multilingües («poor», «pobres», «pauvre», «arm») señalan la carencia económica, aunque el término griego implica tradicionalmente una pobreza laboriosa más que una indigencia desvalida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74444, 'spa', 'Suegra', 'Suegra, la madre del cónyuge. Las traducciones multilingües convergen con precisión: español «suegra», francés «belle-mère», alemán «Schwiegermutter». En los Evangelios aparece en dos contextos: la curación de la suegra de Simón Pedro (Mateo 8:14; Marcos 1:30; Lucas 4:38), que muestra la compasión de Jesús, y la profecía sobre la división familiar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74445, 'spa', 'Suegro', 'El padre del cónyuge de alguien. La identificación que hace Juan de Caifás como suegro de Anás esclarece la dinámica familiar en la casa del sumo sacerdote durante el juicio de Jesús. El término de parentesco aparece en diversas lenguas («father-in-law», «suegro», «beau-père», «Schwiegervater») con notable uniformidad, poniendo de relieve el vínculo familiar entre dos figuras clave del relato de la pasión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74446, 'spa', 'Llorar, lamentarse, hacer duelo — expresar profundo dolor, tristeza o lamentació', 'Llorar, lamentarse, hacer duelo — expresar profundo dolor, tristeza o lamentación, ya sea por muerte, pecado o pérdida catastrófica. Cubre el duelo por fallecimiento (Mc 16:10, los discípulos llorando por Jesús; Mt 9:15, lamentar la ausencia del novio), el dolor espiritual por el pecado (1 Co 5:2, no lamentarse por la inmoralidad congregacional; Stg 4:9, haced duelo y llorad en arrepentimiento), el consuelo escatológico para los afligidos (Mt 5:4) y el lamento por destrucción (Ap 18:11,15,19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74455, 'spa', 'Luto y duelo profundo', 'Luto, duelo o pesar profundo, particularmente la lamentación solemne asociada con la muerte, la catástrofe o una pérdida irreversible. Conlleva fuertes matices de ritual público de duelo. Santiago 4:9 lo emplea como llamado al arrepentimiento, exigiendo que la risa autocomplaciente ceda ante el luto. En Apocalipsis 18, πένθος se convierte en el destino irónico de Babilonia, mientras que Apocalipsis 21:4 promete su abolición definitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74456, 'spa', 'Pobre o necesitado', 'Describe a alguien que carece de recursos materiales. El relato de Lucas destaca la pobreza de la viuda para contrastarla con las grandes ofrendas de los ricos, subrayando la naturaleza sacrificial de su donación. La evidencia multilingüe (''poor'', ''pobre'', ''pauvre'') capta de manera constante la privación económica, que Jesús valora no por la cantidad sino por la proporción y la disposición del corazón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74457, 'spa', 'Cinco veces', 'Adverbio que denota la frecuencia «cinco veces». El catálogo de sufrimientos de Pablo incluye haber recibido el castigo judío de treinta y nueve azotes en cinco ocasiones distintas, lo que pone de relieve la naturaleza reiterada de su persecución. Las glosas multilingües (''five-times'', ''cinco-veces'', ''cinq-fois'', ''fünfmal'') expresan uniformemente la frecuencia numérica, enfatizando el desgaste acumulado de las aflicciones de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74458, 'spa', 'Cinco mil', 'El número cardinal cinco mil, usado exclusivamente en el NT en relación con la alimentación milagrosa de la multitud. Las traducciones son transparentes: español «cinco mil», francés «cinq mille», alemán «fünftausend». Las seis apariciones (Mateo 14:21; 16:9; Marcos 6:44; 8:19; Lucas 9:14; Juan 6:10) se refieren al mismo evento, haciendo de este número un referente icónico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74460, 'spa', 'Cinco — el número cardinal cinco, usado en 38 apariciones del Nuevo Testamento e', 'Cinco — el número cardinal cinco, usado en 38 apariciones del Nuevo Testamento en contextos narrativos, parabólicos y apocalípticos. Los cinco panes que alimentaron a los cinco mil (Mateo 14:17; Marcos 6:38; Lucas 9:13; Juan 6:9), las cinco vírgenes prudentes y las cinco insensatas (Mateo 25:2), y los cinco talentos (Mateo 25:15-20) son ejemplos prominentes. Es un sentido numérico único y unívoco, sin extensión semántica ni desarrollo figurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74462, 'spa', 'Decimoquinto', 'Número ordinal que marca posición o secuencia. La fórmula de datación de Lucas sitúa el ministerio profético de Juan en un momento histórico concreto, correlacionándolo con el reinado de Tiberio y otros gobernantes. La evidencia multilingüe (''fifteenth'', ''decimoquinto'', ''quinzième'') expresa de manera consistente la secuencia ordinal, subrayando la precisión histórica de Lucas y el cumplimiento de la profecía en el tiempo real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74463, 'spa', 'Cincuenta', 'Cincuenta — el numeral cardinal, empleado para grupos de personas (Marcos 6:40; Lucas 9:14), cantidades monetarias (Lucas 7:41), medidas de mercancías (Lucas 16:6) y como indicador de edad en cifras redondas (Juan 8:57). En las narraciones de la alimentación sirve como unidad organizativa de la multitud, mientras que en las parábolas lucanas aparece en cálculos financieros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74464, 'spa', 'Fiesta de Pentecostés', 'Todas las lenguas conservan el nombre: Pentecostés en español, Pentecost en inglés, Pfingsten en alemán. El léxico lo define como el «día quincuagésimo después de la Pascua», vinculado a la Fiesta de las Semanas. Hechos 2:1 marca el derramamiento del Espíritu Santo. Hechos 20:16 y 1 Corintios 16:8 lo mencionan como referencia temporal en el ministerio de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74465, 'spa', 'Confianza y seguridad', 'Un estado asentado de confianza, seguridad o audacia firme, fundamentado en la relación con Dios o en el poder del evangelio. Pablo emplea este término para expresar la certeza interior que posibilita la audacia exterior. El español «confianza» y el francés «confiance» (del latín confidere, «confiar plenamente»), junto con el alemán «Zuversicht», subrayan la firmeza esperanzada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (74470, 'spa', 'La orilla opuesta de un cuerpo de agua o frontera geográfica, usado como preposi', 'La orilla opuesta de un cuerpo de agua o frontera geográfica, usado como preposición (''más allá del Jordán'') o como sustantivo (''el otro lado''). Casi las 23 ocurrencias en el NT se agrupan en torno al Mar de Galilea y el río Jordán. Mateo 4:15 hace eco de Isaías con ''Galilea más allá del Jordán'', mientras que Mat 8:18, 28 y 14:22 narran los cruces de Jesús hacia la otra orilla.');